export type AuditOperation = 'DELETE' | 'INSERT' | 'UPDATE' | 'VIEW';
export type LocalizedStrings = Record<string, string>;
export type ContextTranslations = {
    [operation in AuditOperation]: {
        title: LocalizedStrings;
        description: LocalizedStrings;
    };
};
export interface AuditLogContextData {
    context: string;
    translations: ContextTranslations;
}
